const content = {
  en: {
    title: 'Terms of Service',
    updated: 'Last updated: February 16, 2026',
    sections: [
      { h: '1. Acceptance of Terms', p: 'By accessing or using the ShaPop application ("App"), you agree to be bound by these Terms of Service ("Terms"). If you do not agree, do not use the App. ShaPop is operated by ShaPop Ltd., registered in France.' },
      { h: '2. Eligibility', p: 'You must be at least 18 years old to use ShaPop. By creating an account, you represent that you are of legal age and have the capacity to enter into a binding agreement.' },
      { h: '3. Account Registration', p: 'You must provide accurate and complete information when creating your account. You are responsible for maintaining the confidentiality of your credentials and for all activities under your account. Notify us immediately of any unauthorized use.' },
      { h: '4. Marketplace Rules', p: 'ShaPop is a live-shopping marketplace connecting buyers and sellers. Sellers are independent parties, not employees or agents of ShaPop. ShaPop does not own, manufacture, or inspect items listed. Sellers are solely responsible for the accuracy of listings, item quality, and compliance with applicable laws.' },
      { h: '5. Live Streaming', p: 'When conducting live streams, you agree to: (a) not broadcast prohibited, offensive, or illegal content; (b) not use deceptive practices; (c) comply with all applicable advertising and consumer protection laws; (d) respect other users. ShaPop may terminate streams that violate these rules without notice.' },
      { h: '6. Purchases & Payments', p: 'All purchases are transactions between the buyer and the seller. Prices are set by sellers and displayed in the local currency. ShaPop processes payments through secure third-party providers. A service fee may apply to transactions. Payment terms and fees are displayed before purchase confirmation.' },
      { h: '7. Shipping & Returns', p: 'Sellers are responsible for shipping items within the timeframe specified. Buyers may request a return within 14 days of receipt in accordance with French Consumer Protection Code (Code de la consommation). Refunds are processed to the original payment method within 14 business days of approved return.' },
      { h: '8. Prohibited Items', p: 'The following may not be listed: weapons, drugs, counterfeit goods, stolen property, hazardous materials, tobacco, alcohol (without license), live animals, human remains, and any item prohibited by French law.' },
      { h: '9. Seller Fees & Payouts', p: 'ShaPop charges the following fees on each completed sale, deducted from the seller\'s payout (all amounts include VAT at 20%): (a) Platform commission: 8% of the sale price + VAT = 9.60% effective; (b) Payment processing fee: 2.9% of the sale price + 0.30\u20AC + VAT = 3.48% + 0.36\u20AC effective (Stripe). Example: for a 50\u20AC sale, platform commission is 4.80\u20AC TTC, processing fee is 2.10\u20AC TTC, total fees are 6.90\u20AC, and the seller receives 43.10\u20AC. Payouts are processed weekly to the seller\'s registered bank account, subject to a minimum threshold of 50\u20AC. Fees are subject to change with 30 days\' prior notice.' },
      { h: '10. Intellectual Property', p: 'All ShaPop branding, logos, and app content are the property of ShaPop Ltd. Users retain ownership of content they create but grant ShaPop a worldwide, non-exclusive, royalty-free license to use, display, and distribute such content within the platform.' },
      { h: '11. User Conduct', p: 'You agree not to: (a) violate any law or regulation; (b) harass, threaten, or defraud other users; (c) post false or misleading content; (d) attempt to gain unauthorized access to the App; (e) use bots or automated tools; (f) manipulate reviews or ratings.' },
      { h: '12. Limitation of Liability', p: 'To the maximum extent permitted by law, ShaPop shall not be liable for any indirect, incidental, special, or consequential damages. ShaPop\'s total liability shall not exceed the amount paid by you in the 12 months preceding the claim.' },
      { h: '13. Dispute Resolution', p: 'For disputes between buyers and sellers, ShaPop offers a mediation service. If mediation fails, disputes shall be resolved by the competent courts in Paris, France.' },
      { h: '14. Termination', p: 'ShaPop may suspend or terminate your account at any time for violation of these Terms. You may delete your account at any time through the App settings. Upon termination, outstanding transactions will be completed.' },
      { h: '15. Modifications', p: 'ShaPop reserves the right to modify these Terms at any time. Material changes will be notified via the App or email at least 30 days before taking effect. Continued use after changes constitutes acceptance.' },
      { h: '16. Governing Law', p: 'These Terms are governed by the laws of France. Any legal proceedings shall be brought exclusively in the courts of Paris.' },
      { h: '17. Contact', p: 'For questions about these Terms, contact us at: shapopcontact@gmail.com' },
      { h: 'PROVISIONS SPECIFIC TO MARKETPLACE ACTIVITY', p: '' },
      { h: '18. Role of the Platform', p: 'ShaPop acts as a technical intermediary connecting buyers and sellers through the Application. ShaPop is not the seller of the goods offered and is never a party to the sales contract entered into between the buyer and the seller. The sales contract is formed directly between the buyer and the seller. The seller is solely responsible for the offer, description, conformity, delivery, and after-sales service of the products.' },
      { h: '19. Seller Responsibilities', p: 'The seller warrants that they hold all necessary rights, titles, authorizations, and capacities to offer and sell goods on the platform. The seller warrants that the products comply with all applicable laws and regulations in the countries of origin, destination, and transit. The seller is solely responsible for: the accuracy of descriptions, photographs, and representations of the products; the authenticity and provenance of the items; their tax and reporting obligations; customs formalities, export or import licenses; shipping, transport, insurance, and delivery; handling customer complaints and after-sales service.' },
      { h: '20. Payment Processing', p: 'Payments made on the Application are processed by third-party payment service providers mandated by ShaPop. Use of the service implies acceptance of the terms specific to these providers. ShaPop is authorized to automatically deduct from each transaction its commission, applicable fees, and any amount due for penalties, refunds, disputes, or adjustments before remitting the balance to the seller.' },
      { h: '21. Refunds, Disputes, and Offsets', p: 'In the event of a refund, bank chargeback, suspected fraud, buyer complaint, or violation of payment rules, ShaPop reserves the right to debit the relevant seller\'s account. ShaPop may offset these amounts against pending or future payments, or require direct payment from the seller if available funds are insufficient. The seller irrevocably authorizes these deductions and acknowledges that ultimate financial responsibility for the transaction lies with them.' },
      { h: '22. Security Reserve and Fund Withholding', p: 'ShaPop may, at its sole discretion, delay, suspend, or condition payouts, or establish a financial reserve when a risk level, unusual volume of disputes, suspicion of fraud, or regulatory requirement is identified. This reserve may be maintained for a period reasonably necessary for risk management.' },
      { h: '23. International Shipping and Customs', p: 'For any transaction involving a cross-border shipment, the seller is responsible for compliance with all export-related obligations. The buyer is responsible for customs duties, import taxes, and administrative fees applicable in the destination country. ShaPop does not act as importer, exporter, carrier, or customs declarant.' },
      { h: '24. Compliance with Payment Network Rules', p: 'Users agree to comply with all applicable rules imposed by card networks, financial institutions, and payment service providers used by the platform.' },
      { h: '25. Power of Suspension or Termination', p: 'ShaPop may suspend, restrict, or terminate access to the Application or payment services, immediately and without notice, in the event of legal, regulatory, or financial risk, suspicion of fraud, non-compliance with these terms, or at the request of a competent authority.' },
      { h: '26. Limitation of ShaPop\'s Role', p: 'ShaPop exercises no control over the quality, safety, legality, or conformity of the goods sold. ShaPop\'s liability shall not be engaged in respect of transactions concluded between buyers and sellers, except where required by mandatory legal obligation.' },
      { h: 'SUPPLEMENTARY PROVISIONS \u2013 PAYMENTS, RISKS AND INTERNATIONAL TRANSACTIONS', p: '' },
      { h: '27. Role of ShaPop', p: 'ShaPop acts exclusively as a technical intermediary connecting buyers and sellers. ShaPop is never a party to the sales contract entered into between the buyer and the seller. Each seller remains solely responsible for the products offered, their conformity, their legality, their delivery, and after-sales service.' },
      { h: '28. Conformity of Goods and Capacity to Sell', p: 'The seller warrants that they hold all necessary rights, authorizations, and capacities to offer the goods on the platform. They undertake that the products may be legally sold and shipped to the countries involved in the transaction and to comply with all applicable laws and regulations in the country of origin, transit, and destination.' },
      { h: '29. Payment Processing', p: 'Payments are processed by third-party payment service providers mandated by ShaPop. Use of the platform implies acceptance of the terms of these providers. ShaPop is authorized to automatically deduct its commission, applicable fees, and any amount due for penalties, refunds, or adjustments before remitting the balance to the seller.' },
      { h: '30. Refunds, Disputes, and Chargebacks', p: 'In the event of a refund, payment dispute, bank chargeback, suspected fraud, or violation of the rules imposed by card networks or payment providers, ShaPop reserves the right to debit the relevant seller. ShaPop may offset these amounts against pending or future payments, withhold funds, or require direct repayment from the seller when available funds are insufficient. The seller acknowledges that ultimate financial responsibility for the transaction lies with them.' },
      { h: '31. Security Reserve and Withholding', p: 'In order to manage risk exposure, ShaPop may, at its sole discretion, delay payouts, cap a seller\'s activity, or establish a financial reserve for the period reasonably necessary to cover potential claims.' },
      { h: '32. International Shipping and Customs', p: 'For any cross-border transaction, the seller is responsible for compliance with export obligations and the required declarations. The buyer is responsible for customs duties, import taxes, and administrative fees applicable in the destination country. ShaPop does not act as importer, exporter, carrier, or customs declarant.' },
      { h: '33. Compliance with Payment Rules', p: 'Users agree to comply with all applicable rules imposed by card networks and financial partners used by the platform.' },
      { h: '34. Platform Protection Power', p: 'ShaPop may immediately suspend access to services, block transactions, or withhold funds when a legal, regulatory, financial, or fraud risk is identified, or at the request of a competent authority.' },
    ],
  },
  he: {
    title: '\u05EA\u05E0\u05D0\u05D9 \u05E9\u05D9\u05DE\u05D5\u05E9',
    updated: '\u05E2\u05D3\u05DB\u05D5\u05DF \u05D0\u05D7\u05E8\u05D5\u05DF: 16 \u05D1\u05E4\u05D1\u05E8\u05D5\u05D0\u05E8 2026',
    sections: [
      { h: '1. \u05E7\u05D1\u05DC\u05EA \u05D4\u05EA\u05E0\u05D0\u05D9\u05DD', p: '\u05D1\u05D2\u05D9\u05E9\u05D4 \u05D0\u05D5 \u05E9\u05D9\u05DE\u05D5\u05E9 \u05D1\u05D0\u05E4\u05DC\u05D9\u05E7\u05E6\u05D9\u05D9\u05EA ShaPop ("\u05D4\u05D0\u05E4\u05DC\u05D9\u05E7\u05E6\u05D9\u05D4"), \u05D0\u05EA\u05D4 \u05DE\u05E1\u05DB\u05D9\u05DD \u05DC\u05EA\u05E0\u05D0\u05D9 \u05E9\u05D9\u05DE\u05D5\u05E9 \u05D0\u05DC\u05D4 ("\u05D4\u05EA\u05E0\u05D0\u05D9\u05DD"). \u05D0\u05DD \u05D0\u05D9\u05E0\u05DA \u05DE\u05E1\u05DB\u05D9\u05DD, \u05D0\u05DC \u05EA\u05E9\u05EA\u05DE\u05E9 \u05D1\u05D0\u05E4\u05DC\u05D9\u05E7\u05E6\u05D9\u05D4. ShaPop \u05DE\u05D5\u05E4\u05E2\u05DC\u05EA \u05E2"\u05D9 ShaPop \u05D1\u05E2"\u05DE, \u05D4\u05E8\u05E9\u05D5\u05DE\u05D4 \u05D1\u05E6\u05E8\u05E4\u05EA.' },
      { h: '2. \u05DB\u05E9\u05D9\u05E8\u05D5\u05EA', p: '\u05E2\u05DC\u05D9\u05DA \u05DC\u05D4\u05D9\u05D5\u05EA \u05D1\u05DF 18 \u05DC\u05E4\u05D7\u05D5\u05EA \u05DB\u05D3\u05D9 \u05DC\u05D4\u05E9\u05EA\u05DE\u05E9 \u05D1-ShaPop. \u05D1\u05D9\u05E6\u05D9\u05E8\u05EA \u05D7\u05E9\u05D1\u05D5\u05DF, \u05D0\u05EA\u05D4 \u05DE\u05E6\u05D4\u05D9\u05E8 \u05E9\u05D0\u05EA\u05D4 \u05D1\u05D2\u05D9\u05DC \u05D7\u05D5\u05E7\u05D9 \u05D5\u05D1\u05E2\u05DC \u05DB\u05E9\u05E8\u05D5\u05EA \u05DE\u05E9\u05E4\u05D8\u05D9\u05EA.' },
      { h: '3. \u05D4\u05E8\u05E9\u05DE\u05EA \u05D7\u05E9\u05D1\u05D5\u05DF', p: '\u05E2\u05DC\u05D9\u05DA \u05DC\u05E1\u05E4\u05E7 \u05DE\u05D9\u05D3\u05E2 \u05DE\u05D3\u05D5\u05D9\u05E7 \u05D5\u05DE\u05DC\u05D0 \u05D1\u05E2\u05EA \u05D9\u05E6\u05D9\u05E8\u05EA \u05D4\u05D7\u05E9\u05D1\u05D5\u05DF. \u05D0\u05EA\u05D4 \u05D0\u05D7\u05E8\u05D0\u05D9 \u05DC\u05E9\u05DE\u05D9\u05E8\u05D4 \u05E2\u05DC \u05E1\u05D5\u05D3\u05D9\u05D5\u05EA \u05D4\u05D7\u05E9\u05D1\u05D5\u05DF \u05D5\u05E2\u05DC \u05DB\u05DC \u05D4\u05E4\u05E2\u05D9\u05DC\u05D5\u05EA \u05D1\u05D7\u05E9\u05D1\u05D5\u05E0\u05DA.' },
      { h: '4. \u05DB\u05DC\u05DC\u05D9 \u05D4\u05DE\u05E8\u05E7\u05D8\u05E4\u05DC\u05D9\u05D9\u05E1', p: 'ShaPop \u05D4\u05D9\u05D0 \u05E4\u05DC\u05D8\u05E4\u05D5\u05E8\u05DE\u05EA \u05DE\u05E1\u05D7\u05E8 \u05D7\u05D9 \u05D4\u05DE\u05D7\u05D1\u05E8\u05EA \u05E7\u05D5\u05E0\u05D9\u05DD \u05D5\u05DE\u05D5\u05DB\u05E8\u05D9\u05DD. \u05DE\u05D5\u05DB\u05E8\u05D9\u05DD \u05D4\u05DD \u05E6\u05D3\u05D3\u05D9\u05DD \u05E2\u05E6\u05DE\u05D0\u05D9\u05D9\u05DD. ShaPop \u05D0\u05D9\u05E0\u05D4 \u05D4\u05D1\u05E2\u05DC\u05D9\u05DD \u05E9\u05DC \u05D4\u05DE\u05D5\u05E6\u05E8\u05D9\u05DD \u05D5\u05D0\u05D9\u05E0\u05D4 \u05D1\u05D5\u05D3\u05E7\u05EA \u05D0\u05D5\u05EA\u05DD. \u05D4\u05DE\u05D5\u05DB\u05E8\u05D9\u05DD \u05D0\u05D7\u05E8\u05D0\u05D9\u05DD \u05DC\u05D3\u05D9\u05D5\u05E7 \u05D4\u05DE\u05D5\u05E6\u05E8\u05D9\u05DD \u05D5\u05D0\u05D9\u05DB\u05D5\u05EA\u05DD.' },
      { h: '5. \u05E9\u05D9\u05D3\u05D5\u05E8 \u05D7\u05D9', p: '\u05D1\u05E2\u05EA \u05E9\u05D9\u05D3\u05D5\u05E8 \u05D7\u05D9, \u05D0\u05EA\u05D4 \u05DE\u05E1\u05DB\u05D9\u05DD: (\u05D0) \u05DC\u05D0 \u05DC\u05E9\u05D3\u05E8 \u05EA\u05D5\u05DB\u05DF \u05D0\u05E1\u05D5\u05E8 \u05D0\u05D5 \u05D1\u05DC\u05EA\u05D9 \u05D7\u05D5\u05E7\u05D9; (\u05D1) \u05DC\u05D0 \u05DC\u05D4\u05E9\u05EA\u05DE\u05E9 \u05D1\u05E9\u05D9\u05D8\u05D5\u05EA \u05DE\u05D8\u05E2\u05D5\u05EA; (\u05D2) \u05DC\u05E6\u05D9\u05D9\u05EA \u05D7\u05D5\u05E7\u05D9 \u05D4\u05D2\u05E0\u05EA \u05D4\u05E6\u05E8\u05DB\u05DF; (\u05D3) \u05DC\u05DB\u05D1\u05D3 \u05DE\u05E9\u05EA\u05DE\u05E9\u05D9\u05DD \u05D0\u05D7\u05E8\u05D9\u05DD. ShaPop \u05E8\u05E9\u05D0\u05D9\u05EA \u05DC\u05D4\u05E4\u05E1\u05D9\u05E7 \u05E9\u05D9\u05D3\u05D5\u05E8\u05D9\u05DD \u05D4\u05DE\u05E4\u05E8\u05D9\u05DD \u05DB\u05DC\u05DC\u05D9\u05DD \u05D0\u05DC\u05D4.' },
      { h: '6. \u05E8\u05DB\u05D9\u05E9\u05D5\u05EA \u05D5\u05EA\u05E9\u05DC\u05D5\u05DE\u05D9\u05DD', p: '\u05DB\u05DC \u05E8\u05DB\u05D9\u05E9\u05D4 \u05D4\u05D9\u05D0 \u05E2\u05E1\u05E7\u05D4 \u05D1\u05D9\u05DF \u05D4\u05E7\u05D5\u05E0\u05D4 \u05DC\u05DE\u05D5\u05DB\u05E8. \u05D4\u05DE\u05D7\u05D9\u05E8\u05D9\u05DD \u05E0\u05E7\u05D1\u05E2\u05D9\u05DD \u05E2"\u05D9 \u05D4\u05DE\u05D5\u05DB\u05E8\u05D9\u05DD \u05D1\u05DE\u05D8\u05D1\u05E2 \u05D4\u05DE\u05E7\u05D5\u05DE\u05D9. \u05E2\u05DE\u05DC\u05EA \u05E9\u05D9\u05E8\u05D5\u05EA \u05E2\u05E9\u05D5\u05D9\u05D4 \u05DC\u05D7\u05D5\u05DC \u05E2\u05DC \u05E2\u05E1\u05E7\u05D0\u05D5\u05EA.' },
      { h: '7. \u05DE\u05E9\u05DC\u05D5\u05D7 \u05D5\u05D4\u05D7\u05D6\u05E8\u05D5\u05EA', p: '\u05D4\u05DE\u05D5\u05DB\u05E8\u05D9\u05DD \u05D0\u05D7\u05E8\u05D0\u05D9\u05DD \u05DC\u05DE\u05E9\u05DC\u05D5\u05D7 \u05D1\u05D6\u05DE\u05DF. \u05E7\u05D5\u05E0\u05D9\u05DD \u05E8\u05E9\u05D0\u05D9\u05DD \u05DC\u05D1\u05E7\u05E9 \u05D4\u05D7\u05D6\u05E8\u05D4 \u05EA\u05D5\u05DA 14 \u05D9\u05D5\u05DD \u05D1\u05D4\u05EA\u05D0\u05DD \u05DC\u05E7\u05D5\u05D3 \u05D4\u05D2\u05E0\u05EA \u05D4\u05E6\u05E8\u05DB\u05DF \u05D4\u05E6\u05E8\u05E4\u05EA\u05D9 (Code de la consommation). \u05D4\u05D7\u05D6\u05E8\u05D9\u05DD \u05DB\u05E1\u05E4\u05D9\u05D9\u05DD \u05D9\u05E2\u05D5\u05D1\u05D3\u05D5 \u05EA\u05D5\u05DA 14 \u05D9\u05DE\u05D9 \u05E2\u05E1\u05E7\u05D9\u05DD.' },
      { h: '8. \u05DE\u05D5\u05E6\u05E8\u05D9\u05DD \u05D0\u05E1\u05D5\u05E8\u05D9\u05DD', p: '\u05D0\u05E1\u05D5\u05E8 \u05DC\u05DE\u05DB\u05D5\u05E8: \u05E0\u05E9\u05E7, \u05E1\u05DE\u05D9\u05DD, \u05DE\u05D5\u05E6\u05E8\u05D9\u05DD \u05DE\u05D6\u05D5\u05D9\u05E4\u05D9\u05DD, \u05E8\u05DB\u05D5\u05E9 \u05D2\u05E0\u05D5\u05D1, \u05D7\u05D5\u05DE\u05E8\u05D9\u05DD \u05DE\u05E1\u05D5\u05DB\u05E0\u05D9\u05DD, \u05D8\u05D1\u05E7, \u05D0\u05DC\u05DB\u05D5\u05D4\u05D5\u05DC (\u05DC\u05DC\u05D0 \u05E8\u05D9\u05E9\u05D9\u05D5\u05DF), \u05D7\u05D9\u05D5\u05EA, \u05D5\u05DB\u05DC \u05DE\u05D5\u05E6\u05E8 \u05D4\u05D0\u05E1\u05D5\u05E8 \u05E2\u05DC \u05E4\u05D9 \u05D4\u05D7\u05D5\u05E7 \u05D4\u05E6\u05E8\u05E4\u05EA\u05D9.' },
      { h: '9. \u05E2\u05DE\u05DC\u05D5\u05EA \u05DE\u05D5\u05DB\u05E8\u05D9\u05DD', p: 'ShaPop \u05D2\u05D5\u05D1\u05D4 \u05D0\u05EA \u05D4\u05E2\u05DE\u05DC\u05D5\u05EA \u05D4\u05D1\u05D0\u05D5\u05EA \u05DE\u05DB\u05DC \u05DE\u05DB\u05D9\u05E8\u05D4 (\u05DB\u05D5\u05DC\u05DC \u05DE\u05E2"\u05DE 20%): (\u05D0) \u05E2\u05DE\u05DC\u05EA \u05E4\u05DC\u05D8\u05E4\u05D5\u05E8\u05DE\u05D4: 8% + \u05DE\u05E2"\u05DE = 9.60%; (\u05D1) \u05D3\u05DE\u05D9 \u05E2\u05D9\u05D1\u05D5\u05D3: 2.9% + 0.30\u20AC + \u05DE\u05E2"\u05DE = 3.48% + 0.36\u20AC (Stripe). \u05D3\u05D5\u05D2\u05DE\u05D4: \u05DC\u05DE\u05DB\u05D9\u05E8\u05D4 \u05E9\u05DC 50\u20AC, \u05E2\u05DE\u05DC\u05D5\u05EA 6.90\u20AC, \u05D4\u05DE\u05D5\u05DB\u05E8 \u05DE\u05E7\u05D1\u05DC 43.10\u20AC. \u05EA\u05E9\u05DC\u05D5\u05DE\u05D9\u05DD \u05E9\u05D1\u05D5\u05E2\u05D9\u05D9\u05DD. \u05E1\u05E3 \u05DE\u05D9\u05E0\u05D9\u05DE\u05D5\u05DD: 50\u20AC.' },
      { h: '10. \u05E7\u05E0\u05D9\u05D9\u05DF \u05E8\u05D5\u05D7\u05E0\u05D9', p: '\u05DB\u05DC \u05D4\u05DE\u05D9\u05EA\u05D5\u05D2, \u05DC\u05D5\u05D2\u05D5\u05D0\u05D9\u05DD \u05D5\u05EA\u05D5\u05DB\u05DF \u05D4\u05D0\u05E4\u05DC\u05D9\u05E7\u05E6\u05D9\u05D4 \u05E9\u05D9\u05D9\u05DB\u05D9\u05DD \u05DC-ShaPop. \u05DE\u05E9\u05EA\u05DE\u05E9\u05D9\u05DD \u05E9\u05D5\u05DE\u05E8\u05D9\u05DD \u05D1\u05E2\u05DC\u05D5\u05EA \u05E2\u05DC \u05D4\u05EA\u05D5\u05DB\u05DF \u05E9\u05DC\u05D4\u05DD \u05D0\u05DA \u05DE\u05E2\u05E0\u05D9\u05E7\u05D9\u05DD \u05DC-ShaPop \u05E8\u05D9\u05E9\u05D9\u05D5\u05DF \u05DC\u05D4\u05E9\u05EA\u05DE\u05E9 \u05D1\u05D5 \u05D1\u05E4\u05DC\u05D8\u05E4\u05D5\u05E8\u05DE\u05D4.' },
      { h: '11. \u05D4\u05EA\u05E0\u05D4\u05D2\u05D5\u05EA \u05DE\u05E9\u05EA\u05DE\u05E9\u05D9\u05DD', p: '\u05D0\u05EA\u05D4 \u05DE\u05EA\u05D7\u05D9\u05D9\u05D1 \u05DC\u05D0: (\u05D0) \u05DC\u05D4\u05E4\u05E8 \u05D7\u05D5\u05E7; (\u05D1) \u05DC\u05D4\u05D8\u05E8\u05D9\u05D3 \u05D0\u05D5 \u05DC\u05D4\u05D5\u05E0\u05D5\u05EA; (\u05D2) \u05DC\u05E4\u05E8\u05E1\u05DD \u05EA\u05D5\u05DB\u05DF \u05E9\u05E7\u05E8\u05D9; (\u05D3) \u05DC\u05E0\u05E1\u05D5\u05EA \u05DC\u05D2\u05E9\u05EA \u05DC\u05D0 \u05DE\u05D5\u05E8\u05E9\u05D9\u05EA; (\u05D4) \u05DC\u05D4\u05E9\u05EA\u05DE\u05E9 \u05D1\u05D1\u05D5\u05D8\u05D9\u05DD; (\u05D5) \u05DC\u05D6\u05D9\u05D9\u05E3 \u05D1\u05D9\u05E7\u05D5\u05E8\u05D5\u05EA.' },
      { h: '12. \u05D4\u05D2\u05D1\u05DC\u05EA \u05D0\u05D7\u05E8\u05D9\u05D5\u05EA', p: '\u05D1\u05DE\u05D9\u05D3\u05D4 \u05D4\u05DE\u05E8\u05D1\u05D9\u05EA \u05D4\u05DE\u05D5\u05EA\u05E8\u05EA \u05D1\u05D7\u05D5\u05E7, ShaPop \u05DC\u05D0 \u05EA\u05D9\u05E9\u05D0 \u05D1\u05D0\u05D7\u05E8\u05D9\u05D5\u05EA \u05DC\u05E0\u05D6\u05E7\u05D9\u05DD \u05E2\u05E7\u05D9\u05E4\u05D9\u05DD. \u05D0\u05D7\u05E8\u05D9\u05D5\u05EA ShaPop \u05DC\u05D0 \u05EA\u05E2\u05DC\u05D4 \u05E2\u05DC \u05D4\u05E1\u05DB\u05D5\u05DD \u05E9\u05E9\u05D5\u05DC\u05DD \u05D1-12 \u05D4\u05D7\u05D5\u05D3\u05E9\u05D9\u05DD \u05D4\u05D0\u05D7\u05E8\u05D5\u05E0\u05D9\u05DD.' },
      { h: '13. \u05D9\u05D9\u05E9\u05D5\u05D1 \u05E1\u05DB\u05E1\u05D5\u05DB\u05D9\u05DD', p: '\u05DC\u05E1\u05DB\u05E1\u05D5\u05DB\u05D9\u05DD \u05D1\u05D9\u05DF \u05E7\u05D5\u05E0\u05D9\u05DD \u05DC\u05DE\u05D5\u05DB\u05E8\u05D9\u05DD, ShaPop \u05DE\u05E6\u05D9\u05E2\u05D4 \u05E9\u05D9\u05E8\u05D5\u05EA \u05D2\u05D9\u05E9\u05D5\u05E8. \u05D0\u05DD \u05D4\u05D2\u05D9\u05E9\u05D5\u05E8 \u05E0\u05DB\u05E9\u05DC, \u05D4\u05E1\u05DB\u05E1\u05D5\u05DB\u05D9\u05DD \u05D9\u05D5\u05DB\u05E8\u05E2\u05D5 \u05D1\u05D1\u05EA\u05D9 \u05D4\u05DE\u05E9\u05E4\u05D8 \u05D4\u05DE\u05D5\u05E1\u05DE\u05DB\u05D9\u05DD \u05D1\u05E4\u05E8\u05D9\u05D6.' },
      { h: '14. \u05E1\u05D9\u05D5\u05DD', p: 'ShaPop \u05E8\u05E9\u05D0\u05D9\u05EA \u05DC\u05D4\u05E9\u05E2\u05D5\u05EA \u05D0\u05D5 \u05DC\u05E1\u05D2\u05D5\u05E8 \u05D7\u05E9\u05D1\u05D5\u05E0\u05DA \u05D1\u05DB\u05DC \u05E2\u05EA \u05E2\u05E7\u05D1 \u05D4\u05E4\u05E8\u05EA \u05EA\u05E0\u05D0\u05D9\u05DD \u05D0\u05DC\u05D4. \u05D0\u05EA\u05D4 \u05E8\u05E9\u05D0\u05D9 \u05DC\u05DE\u05D7\u05D5\u05E7 \u05D7\u05E9\u05D1\u05D5\u05E0\u05DA \u05D1\u05DB\u05DC \u05E2\u05EA. \u05E2\u05E1\u05E7\u05D0\u05D5\u05EA \u05E4\u05EA\u05D5\u05D7\u05D5\u05EA \u05D9\u05D5\u05E9\u05DC\u05DE\u05D5.' },
      { h: '15. \u05E9\u05D9\u05E0\u05D5\u05D9\u05D9\u05DD', p: 'ShaPop \u05E9\u05D5\u05DE\u05E8\u05EA \u05DC\u05E2\u05E6\u05DE\u05D4 \u05D0\u05EA \u05D4\u05D6\u05DB\u05D5\u05EA \u05DC\u05E9\u05E0\u05D5\u05EA \u05EA\u05E0\u05D0\u05D9\u05DD \u05D0\u05DC\u05D4. \u05E9\u05D9\u05E0\u05D5\u05D9\u05D9\u05DD \u05DE\u05D4\u05D5\u05EA\u05D9\u05D9\u05DD \u05D9\u05D5\u05D3\u05E2\u05D5 30 \u05D9\u05D5\u05DD \u05DE\u05E8\u05D0\u05E9.' },
      { h: '16. \u05D3\u05D9\u05DF \u05D7\u05DC', p: '\u05EA\u05E0\u05D0\u05D9\u05DD \u05D0\u05DC\u05D4 \u05DB\u05E4\u05D5\u05E4\u05D9\u05DD \u05DC\u05D3\u05D9\u05E0\u05D9 \u05E6\u05E8\u05E4\u05EA. \u05DB\u05DC \u05D4\u05DC\u05D9\u05DA \u05DE\u05E9\u05E4\u05D8\u05D9 \u05D9\u05EA\u05E0\u05D4\u05DC \u05D1\u05D1\u05EA\u05D9 \u05D4\u05DE\u05E9\u05E4\u05D8 \u05D1\u05E4\u05E8\u05D9\u05D6.' },
      { h: '17. \u05E6\u05D5\u05E8 \u05E7\u05E9\u05E8', p: '\u05DC\u05E9\u05D0\u05DC\u05D5\u05EA \u05DC\u05D2\u05D1\u05D9 \u05EA\u05E0\u05D0\u05D9\u05DD \u05D0\u05DC\u05D4, \u05E4\u05E0\u05D5 \u05D0\u05DC\u05D9\u05E0\u05D5: shapopcontact@gmail.com' },
      { h: '\u05D4\u05D5\u05E8\u05D0\u05D5\u05EA \u05E1\u05E4\u05E6\u05D9\u05E4\u05D9\u05D5\u05EA \u05DC\u05E4\u05E2\u05D9\u05DC\u05D5\u05EA \u05D4\u05DE\u05E8\u05E7\u05D8\u05E4\u05DC\u05D9\u05D9\u05E1', p: '' },
      { h: '18. \u05EA\u05E4\u05E7\u05D9\u05D3 \u05D4\u05E4\u05DC\u05D8\u05E4\u05D5\u05E8\u05DE\u05D4', p: 'ShaPop \u05E4\u05D5\u05E2\u05DC\u05EA \u05DB\u05DE\u05EA\u05D5\u05D5\u05DA \u05D8\u05DB\u05E0\u05D9 \u05D4\u05DE\u05D7\u05D1\u05E8 \u05D1\u05D9\u05DF \u05E7\u05D5\u05E0\u05D9\u05DD \u05DC\u05DE\u05D5\u05DB\u05E8\u05D9\u05DD \u05D3\u05E8\u05DA \u05D4\u05D0\u05E4\u05DC\u05D9\u05E7\u05E6\u05D9\u05D4. ShaPop \u05D0\u05D9\u05E0\u05D4 \u05D4\u05DE\u05D5\u05DB\u05E8\u05EA \u05E9\u05DC \u05D4\u05DE\u05D5\u05E6\u05E8\u05D9\u05DD \u05D5\u05D0\u05D9\u05E0\u05D4 \u05E6\u05D3 \u05DC\u05D7\u05D5\u05D6\u05D4 \u05D4\u05DE\u05DB\u05D9\u05E8\u05D4 \u05D1\u05D9\u05DF \u05D4\u05E7\u05D5\u05E0\u05D4 \u05DC\u05DE\u05D5\u05DB\u05E8. \u05D7\u05D5\u05D6\u05D4 \u05D4\u05DE\u05DB\u05D9\u05E8\u05D4 \u05E0\u05DB\u05E8\u05EA \u05D9\u05E9\u05D9\u05E8\u05D5\u05EA \u05D1\u05D9\u05DF \u05D4\u05E7\u05D5\u05E0\u05D4 \u05DC\u05DE\u05D5\u05DB\u05E8. \u05D4\u05DE\u05D5\u05DB\u05E8 \u05D0\u05D7\u05E8\u05D0\u05D9 \u05D1\u05DC\u05E2\u05D3\u05D9\u05EA \u05DC\u05D4\u05E6\u05E2\u05D4, \u05EA\u05D9\u05D0\u05D5\u05E8, \u05D4\u05EA\u05D0\u05DE\u05D4, \u05DE\u05E9\u05DC\u05D5\u05D7 \u05D5\u05E9\u05D9\u05E8\u05D5\u05EA \u05DC\u05D0\u05D7\u05E8 \u05D4\u05DE\u05DB\u05D9\u05E8\u05D4.' },
      { h: '19. \u05D0\u05D7\u05E8\u05D9\u05D5\u05EA \u05D4\u05DE\u05D5\u05DB\u05E8', p: '\u05D4\u05DE\u05D5\u05DB\u05E8 \u05DE\u05EA\u05D7\u05D9\u05D9\u05D1 \u05E9\u05D9\u05E9 \u05DC\u05D5 \u05D0\u05EA \u05DB\u05DC \u05D4\u05D6\u05DB\u05D5\u05D9\u05D5\u05EA, \u05D4\u05D4\u05E8\u05E9\u05D0\u05D5\u05EA \u05D5\u05D4\u05D9\u05DB\u05D5\u05DC\u05D5\u05EA \u05D4\u05E0\u05D3\u05E8\u05E9\u05D5\u05EA \u05DC\u05D4\u05E6\u05D9\u05E2 \u05D5\u05DC\u05DE\u05DB\u05D5\u05E8 \u05DE\u05D5\u05E6\u05E8\u05D9\u05DD \u05D1\u05E4\u05DC\u05D8\u05E4\u05D5\u05E8\u05DE\u05D4. \u05D4\u05DE\u05D5\u05DB\u05E8 \u05DE\u05EA\u05D7\u05D9\u05D9\u05D1 \u05E9\u05D4\u05DE\u05D5\u05E6\u05E8\u05D9\u05DD \u05E2\u05D5\u05DE\u05D3\u05D9\u05DD \u05D1\u05DB\u05DC \u05D4\u05D7\u05D5\u05E7\u05D9\u05DD \u05D5\u05D4\u05EA\u05E7\u05E0\u05D5\u05EA. \u05D4\u05DE\u05D5\u05DB\u05E8 \u05D0\u05D7\u05E8\u05D0\u05D9 \u05D1\u05DC\u05E2\u05D3\u05D9\u05EA \u05DC: \u05D3\u05D9\u05D5\u05E7 \u05D4\u05EA\u05D9\u05D0\u05D5\u05E8\u05D9\u05DD \u05D5\u05D4\u05EA\u05DE\u05D5\u05E0\u05D5\u05EA; \u05D0\u05D5\u05EA\u05E0\u05D8\u05D9\u05D5\u05EA \u05D5\u05DE\u05E7\u05D5\u05E8 \u05D4\u05DE\u05D5\u05E6\u05E8\u05D9\u05DD; \u05D7\u05D5\u05D1\u05D5\u05EA \u05DE\u05E1 \u05D5\u05D3\u05D9\u05D5\u05D5\u05D7; \u05E0\u05D4\u05DC\u05D9 \u05DE\u05DB\u05E1, \u05E8\u05D9\u05E9\u05D9\u05D5\u05E0\u05D5\u05EA \u05D9\u05D9\u05E6\u05D5\u05D0 \u05D0\u05D5 \u05D9\u05D9\u05D1\u05D5\u05D0; \u05DE\u05E9\u05DC\u05D5\u05D7, \u05D4\u05D5\u05D1\u05DC\u05D4, \u05D1\u05D9\u05D8\u05D5\u05D7 \u05D5\u05D0\u05E1\u05E4\u05E7\u05D4; \u05D8\u05D9\u05E4\u05D5\u05DC \u05D1\u05EA\u05DC\u05D5\u05E0\u05D5\u05EA \u05DC\u05E7\u05D5\u05D7\u05D5\u05EA \u05D5\u05E9\u05D9\u05E8\u05D5\u05EA \u05DC\u05D0\u05D7\u05E8 \u05D4\u05DE\u05DB\u05D9\u05E8\u05D4.' },
      { h: '20. \u05E2\u05D9\u05D1\u05D5\u05D3 \u05EA\u05E9\u05DC\u05D5\u05DE\u05D9\u05DD', p: '\u05EA\u05E9\u05DC\u05D5\u05DE\u05D9\u05DD \u05D1\u05D0\u05E4\u05DC\u05D9\u05E7\u05E6\u05D9\u05D4 \u05DE\u05E2\u05D5\u05D1\u05D3\u05D9\u05DD \u05E2\u05DC \u05D9\u05D3\u05D9 \u05E1\u05E4\u05E7\u05D9 \u05E9\u05D9\u05E8\u05D5\u05EA\u05D9 \u05EA\u05E9\u05DC\u05D5\u05DD \u05E6\u05D3 \u05E9\u05DC\u05D9\u05E9\u05D9 \u05D1\u05D4\u05E8\u05E9\u05D0\u05EA ShaPop. \u05D4\u05E9\u05D9\u05DE\u05D5\u05E9 \u05D1\u05E9\u05D9\u05E8\u05D5\u05EA \u05DE\u05D4\u05D5\u05D5\u05D4 \u05E7\u05D1\u05DC\u05EA \u05D4\u05EA\u05E0\u05D0\u05D9\u05DD \u05E9\u05DC \u05E1\u05E4\u05E7\u05D9\u05DD \u05D0\u05DC\u05D4. ShaPop \u05DE\u05D5\u05E8\u05E9\u05D9\u05EA \u05DC\u05E0\u05DB\u05D5\u05EA \u05D0\u05D5\u05D8\u05D5\u05DE\u05D8\u05D9\u05EA \u05DE\u05DB\u05DC \u05E2\u05E1\u05E7\u05D4 \u05D0\u05EA \u05D4\u05E2\u05DE\u05DC\u05D4, \u05D4\u05D3\u05DE\u05D9\u05DD, \u05D5\u05DB\u05DC \u05E1\u05DB\u05D5\u05DD \u05D4\u05DE\u05D2\u05D9\u05E2 \u05D1\u05D2\u05D9\u05DF \u05E7\u05E0\u05E1\u05D5\u05EA, \u05D4\u05D7\u05D6\u05E8\u05D9\u05DD, \u05E1\u05DB\u05E1\u05D5\u05DB\u05D9\u05DD \u05D0\u05D5 \u05D4\u05EA\u05D0\u05DE\u05D5\u05EA \u05DC\u05E4\u05E0\u05D9 \u05D4\u05E2\u05D1\u05E8\u05EA \u05D4\u05D9\u05EA\u05E8\u05D4 \u05DC\u05DE\u05D5\u05DB\u05E8.' },
      { h: '21. \u05D4\u05D7\u05D6\u05E8\u05D9\u05DD, \u05E2\u05E8\u05E2\u05D5\u05E8\u05D9\u05DD \u05D5\u05E7\u05D9\u05D6\u05D5\u05D6\u05D9\u05DD', p: '\u05D1\u05DE\u05E7\u05E8\u05D4 \u05E9\u05DC \u05D4\u05D7\u05D6\u05E8, \u05D4\u05D7\u05D6\u05E8 \u05D1\u05E0\u05E7\u05D0\u05D9 (chargeback), \u05D7\u05E9\u05D3 \u05DC\u05D4\u05D5\u05E0\u05D0\u05D4, \u05EA\u05DC\u05D5\u05E0\u05EA \u05E7\u05D5\u05E0\u05D4 \u05D0\u05D5 \u05D4\u05E4\u05E8\u05EA \u05DB\u05DC\u05DC\u05D9 \u05D4\u05EA\u05E9\u05DC\u05D5\u05DD, ShaPop \u05E9\u05D5\u05DE\u05E8\u05EA \u05DC\u05E2\u05E6\u05DE\u05D4 \u05D0\u05EA \u05D4\u05D6\u05DB\u05D5\u05EA \u05DC\u05D7\u05D9\u05D9\u05D1 \u05D0\u05EA \u05D7\u05E9\u05D1\u05D5\u05DF \u05D4\u05DE\u05D5\u05DB\u05E8. ShaPop \u05E8\u05E9\u05D0\u05D9\u05EA \u05DC\u05E7\u05D6\u05D6 \u05E1\u05DB\u05D5\u05DE\u05D9\u05DD \u05D0\u05DC\u05D4 \u05DE\u05D5\u05DC \u05EA\u05E9\u05DC\u05D5\u05DE\u05D9\u05DD \u05DE\u05DE\u05EA\u05D9\u05E0\u05D9\u05DD \u05D0\u05D5 \u05E2\u05EA\u05D9\u05D3\u05D9\u05D9\u05DD, \u05D0\u05D5 \u05DC\u05D3\u05E8\u05D5\u05E9 \u05EA\u05E9\u05DC\u05D5\u05DD \u05D9\u05E9\u05D9\u05E8 \u05DE\u05D4\u05DE\u05D5\u05DB\u05E8. \u05D4\u05DE\u05D5\u05DB\u05E8 \u05DE\u05D0\u05E9\u05E8 \u05D1\u05D0\u05D5\u05E4\u05DF \u05D1\u05DC\u05EA\u05D9 \u05D7\u05D5\u05D6\u05E8 \u05E0\u05D9\u05DB\u05D5\u05D9\u05D9\u05DD \u05D0\u05DC\u05D4 \u05D5\u05DE\u05D0\u05E9\u05E8 \u05E9\u05D4\u05D0\u05D7\u05E8\u05D9\u05D5\u05EA \u05D4\u05E4\u05D9\u05E0\u05E0\u05E1\u05D9\u05EA \u05D4\u05E1\u05D5\u05E4\u05D9\u05EA \u05DC\u05E2\u05E1\u05E7\u05D4 \u05D7\u05DC\u05D4 \u05E2\u05DC\u05D9\u05D5.' },
      { h: '22. \u05E8\u05D6\u05E8\u05D1\u05EA \u05D1\u05D9\u05D8\u05D7\u05D5\u05DF \u05D5\u05E2\u05D9\u05DB\u05D5\u05D1 \u05DB\u05E1\u05E4\u05D9\u05DD', p: 'ShaPop \u05E8\u05E9\u05D0\u05D9\u05EA, \u05DC\u05E4\u05D9 \u05E9\u05D9\u05E7\u05D5\u05DC \u05D3\u05E2\u05EA\u05D4 \u05D4\u05D1\u05DC\u05E2\u05D3\u05D9, \u05DC\u05E2\u05DB\u05D1, \u05DC\u05D4\u05E9\u05D4\u05D5\u05EA \u05D0\u05D5 \u05DC\u05D4\u05EA\u05E0\u05D5\u05EA \u05D4\u05E2\u05D1\u05E8\u05D5\u05EA, \u05D0\u05D5 \u05DC\u05D4\u05E7\u05D9\u05DD \u05E8\u05D6\u05E8\u05D1\u05D4 \u05E4\u05D9\u05E0\u05E0\u05E1\u05D9\u05EA \u05DB\u05D0\u05E9\u05E8 \u05DE\u05D6\u05D5\u05D4\u05D4 \u05E8\u05DE\u05EA \u05E1\u05D9\u05DB\u05D5\u05DF, \u05E0\u05E4\u05D7 \u05D7\u05E8\u05D9\u05D2 \u05E9\u05DC \u05E1\u05DB\u05E1\u05D5\u05DB\u05D9\u05DD, \u05D7\u05E9\u05D3 \u05DC\u05D4\u05D5\u05E0\u05D0\u05D4 \u05D0\u05D5 \u05D3\u05E8\u05D9\u05E9\u05D4 \u05E8\u05D2\u05D5\u05DC\u05D8\u05D5\u05E8\u05D9\u05EA. \u05E8\u05D6\u05E8\u05D1\u05D4 \u05D6\u05D5 \u05E2\u05E9\u05D5\u05D9\u05D4 \u05DC\u05D4\u05D9\u05E9\u05DE\u05E8 \u05DC\u05DE\u05E9\u05DA \u05D4\u05D6\u05DE\u05DF \u05D4\u05E0\u05D3\u05E8\u05E9 \u05DC\u05E0\u05D9\u05D4\u05D5\u05DC \u05D4\u05E1\u05D9\u05DB\u05D5\u05DF.' },
      { h: '23. \u05DE\u05E9\u05DC\u05D5\u05D7 \u05D1\u05D9\u05E0\u05DC\u05D0\u05D5\u05DE\u05D9 \u05D5\u05DE\u05DB\u05E1', p: '\u05DC\u05DB\u05DC \u05E2\u05E1\u05E7\u05D4 \u05D4\u05DB\u05D5\u05DC\u05DC\u05EA \u05DE\u05E9\u05DC\u05D5\u05D7 \u05D7\u05D5\u05E6\u05D4 \u05D2\u05D1\u05D5\u05DC\u05D5\u05EA, \u05D4\u05DE\u05D5\u05DB\u05E8 \u05D0\u05D7\u05E8\u05D0\u05D9 \u05DC\u05E2\u05DE\u05D9\u05D3\u05D4 \u05D1\u05DB\u05DC \u05D4\u05D7\u05D5\u05D1\u05D5\u05EA \u05D4\u05E7\u05E9\u05D5\u05E8\u05D5\u05EA \u05DC\u05D9\u05D9\u05E6\u05D5\u05D0. \u05D4\u05E7\u05D5\u05E0\u05D4 \u05D0\u05D7\u05E8\u05D0\u05D9 \u05DC\u05DE\u05DB\u05E1\u05D9 \u05DE\u05DB\u05E1, \u05DE\u05D9\u05E1\u05D9 \u05D9\u05D9\u05D1\u05D5\u05D0 \u05D5\u05D3\u05DE\u05D9 \u05D0\u05D3\u05DE\u05D9\u05E0\u05D9\u05E1\u05D8\u05E8\u05E6\u05D9\u05D4 \u05D1\u05DE\u05D3\u05D9\u05E0\u05EA \u05D4\u05D9\u05E2\u05D3. ShaPop \u05D0\u05D9\u05E0\u05D4 \u05E4\u05D5\u05E2\u05DC\u05EA \u05DB\u05D9\u05D9\u05D1\u05D0\u05E0\u05D9\u05EA, \u05D9\u05D9\u05E6\u05D5\u05D0\u05E0\u05D9\u05EA, \u05DE\u05D5\u05D1\u05D9\u05DC\u05D4 \u05D0\u05D5 \u05DE\u05E6\u05D4\u05D9\u05E8\u05EA \u05DE\u05DB\u05E1.' },
      { h: '24. \u05E2\u05DE\u05D9\u05D3\u05D4 \u05D1\u05DB\u05DC\u05DC\u05D9 \u05E8\u05E9\u05EA\u05D5\u05EA \u05D4\u05EA\u05E9\u05DC\u05D5\u05DD', p: '\u05D4\u05DE\u05E9\u05EA\u05DE\u05E9\u05D9\u05DD \u05DE\u05E1\u05DB\u05D9\u05DE\u05D9\u05DD \u05DC\u05E6\u05D9\u05D9\u05EA \u05D0\u05EA \u05DB\u05DC \u05D4\u05DB\u05DC\u05DC\u05D9\u05DD \u05D4\u05D7\u05DC\u05D9\u05DD \u05E9\u05DC \u05E8\u05E9\u05EA\u05D5\u05EA \u05D4\u05DB\u05E8\u05D8\u05D9\u05E1\u05D9\u05DD, \u05DE\u05D5\u05E1\u05D3\u05D5\u05EA \u05E4\u05D9\u05E0\u05E0\u05E1\u05D9\u05D9\u05DD \u05D5\u05E1\u05E4\u05E7\u05D9 \u05E9\u05D9\u05E8\u05D5\u05EA\u05D9 \u05EA\u05E9\u05DC\u05D5\u05DD \u05D4\u05DE\u05E9\u05DE\u05E9\u05D9\u05DD \u05D0\u05EA \u05D4\u05E4\u05DC\u05D8\u05E4\u05D5\u05E8\u05DE\u05D4.' },
      { h: '25. \u05E1\u05DE\u05DB\u05D5\u05EA \u05D4\u05E9\u05E2\u05D9\u05D4 \u05D0\u05D5 \u05E1\u05D9\u05D5\u05DD', p: 'ShaPop \u05E8\u05E9\u05D0\u05D9\u05EA \u05DC\u05D4\u05E9\u05E2\u05D5\u05EA, \u05DC\u05D4\u05D2\u05D1\u05D9\u05DC \u05D0\u05D5 \u05DC\u05E1\u05D9\u05D9\u05DD \u05D0\u05EA \u05D4\u05D2\u05D9\u05E9\u05D4 \u05DC\u05D0\u05E4\u05DC\u05D9\u05E7\u05E6\u05D9\u05D4 \u05D0\u05D5 \u05DC\u05E9\u05D9\u05E8\u05D5\u05EA\u05D9 \u05D4\u05EA\u05E9\u05DC\u05D5\u05DD, \u05D1\u05D0\u05D5\u05E4\u05DF \u05DE\u05D9\u05D9\u05D3\u05D9 \u05D5\u05DC\u05DC\u05D0 \u05D4\u05D5\u05D3\u05E2\u05D4 \u05DE\u05D5\u05E7\u05D3\u05DE\u05EA, \u05D1\u05DE\u05E7\u05E8\u05D4 \u05E9\u05DC \u05E1\u05D9\u05DB\u05D5\u05DF \u05DE\u05E9\u05E4\u05D8\u05D9, \u05E8\u05D2\u05D5\u05DC\u05D8\u05D5\u05E8\u05D9 \u05D0\u05D5 \u05E4\u05D9\u05E0\u05E0\u05E1\u05D9, \u05D7\u05E9\u05D3 \u05DC\u05D4\u05D5\u05E0\u05D0\u05D4, \u05D0\u05D9-\u05E2\u05DE\u05D9\u05D3\u05D4 \u05D1\u05EA\u05E0\u05D0\u05D9\u05DD \u05D0\u05D5 \u05DC\u05D1\u05E7\u05E9\u05EA \u05E8\u05E9\u05D5\u05EA \u05DE\u05D5\u05E1\u05DE\u05DB\u05EA.' },
      { h: '26. \u05D4\u05D2\u05D1\u05DC\u05EA \u05EA\u05E4\u05E7\u05D9\u05D3 ShaPop', p: 'ShaPop \u05D0\u05D9\u05E0\u05D4 \u05DE\u05E4\u05E7\u05D7\u05EA \u05E2\u05DC \u05D0\u05D9\u05DB\u05D5\u05EA, \u05D1\u05D8\u05D9\u05D7\u05D5\u05EA, \u05D7\u05D5\u05E7\u05D9\u05D5\u05EA \u05D0\u05D5 \u05D4\u05EA\u05D0\u05DE\u05EA \u05D4\u05DE\u05D5\u05E6\u05E8\u05D9\u05DD \u05D4\u05E0\u05DE\u05DB\u05E8\u05D9\u05DD. \u05D0\u05D7\u05E8\u05D9\u05D5\u05EA ShaPop \u05DC\u05D0 \u05EA\u05D7\u05D5\u05DC \u05D1\u05D2\u05D9\u05DF \u05E2\u05E1\u05E7\u05D0\u05D5\u05EA \u05D1\u05D9\u05DF \u05E7\u05D5\u05E0\u05D9\u05DD \u05DC\u05DE\u05D5\u05DB\u05E8\u05D9\u05DD, \u05DC\u05DE\u05E2\u05D8 \u05D7\u05D5\u05D1\u05D4 \u05D7\u05D5\u05E7\u05D9\u05EA \u05D4\u05DB\u05E8\u05D7\u05D9\u05EA.' },
      { h: '\u05D4\u05D5\u05E8\u05D0\u05D5\u05EA \u05DE\u05E9\u05DC\u05D9\u05DE\u05D5\u05EA \u2013 \u05EA\u05E9\u05DC\u05D5\u05DE\u05D9\u05DD, \u05E1\u05D9\u05DB\u05D5\u05E0\u05D9\u05DD \u05D5\u05E2\u05E1\u05E7\u05D0\u05D5\u05EA \u05D1\u05D9\u05E0\u05DC\u05D0\u05D5\u05DE\u05D9\u05D5\u05EA', p: '' },
      { h: '27. \u05EA\u05E4\u05E7\u05D9\u05D3 ShaPop', p: 'ShaPop \u05E4\u05D5\u05E2\u05DC\u05EA \u05D0\u05DA \u05D5\u05E8\u05E7 \u05DB\u05DE\u05EA\u05D5\u05D5\u05DA \u05D8\u05DB\u05E0\u05D9 \u05D4\u05DE\u05D7\u05D1\u05E8 \u05D1\u05D9\u05DF \u05E7\u05D5\u05E0\u05D9\u05DD \u05DC\u05DE\u05D5\u05DB\u05E8\u05D9\u05DD. ShaPop \u05D0\u05D9\u05E0\u05D4 \u05DC\u05E2\u05D5\u05DC\u05DD \u05E6\u05D3 \u05DC\u05D7\u05D5\u05D6\u05D4 \u05D4\u05DE\u05DB\u05D9\u05E8\u05D4 \u05D1\u05D9\u05DF \u05D4\u05E7\u05D5\u05E0\u05D4 \u05DC\u05DE\u05D5\u05DB\u05E8. \u05DB\u05DC \u05DE\u05D5\u05DB\u05E8 \u05E0\u05D5\u05E9\u05D0 \u05D1\u05D0\u05D7\u05E8\u05D9\u05D5\u05EA \u05D4\u05D1\u05DC\u05E2\u05D3\u05D9\u05EA \u05DC\u05DE\u05D5\u05E6\u05E8\u05D9\u05DD \u05D4\u05DE\u05D5\u05E6\u05E2\u05D9\u05DD, \u05DC\u05D4\u05EA\u05D0\u05DE\u05EA\u05DD, \u05DC\u05D7\u05D5\u05E7\u05D9\u05D5\u05EA\u05DD, \u05DC\u05DE\u05E9\u05DC\u05D5\u05D7 \u05D5\u05DC\u05E9\u05D9\u05E8\u05D5\u05EA \u05DC\u05D0\u05D7\u05E8 \u05D4\u05DE\u05DB\u05D9\u05E8\u05D4.' },
      { h: '28. \u05D4\u05EA\u05D0\u05DE\u05EA \u05DE\u05D5\u05E6\u05E8\u05D9\u05DD \u05D5\u05DB\u05E9\u05D9\u05E8\u05D5\u05EA \u05DC\u05DE\u05DB\u05D5\u05E8', p: '\u05D4\u05DE\u05D5\u05DB\u05E8 \u05DE\u05EA\u05D7\u05D9\u05D9\u05D1 \u05E9\u05D9\u05E9 \u05DC\u05D5 \u05D0\u05EA \u05DB\u05DC \u05D4\u05D6\u05DB\u05D5\u05D9\u05D5\u05EA, \u05D4\u05D4\u05E8\u05E9\u05D0\u05D5\u05EA \u05D5\u05D4\u05D9\u05DB\u05D5\u05DC\u05D5\u05EA \u05D4\u05E0\u05D3\u05E8\u05E9\u05D5\u05EA \u05DC\u05D4\u05E6\u05D9\u05E2 \u05DE\u05D5\u05E6\u05E8\u05D9\u05DD \u05D1\u05E4\u05DC\u05D8\u05E4\u05D5\u05E8\u05DE\u05D4. \u05D4\u05D5\u05D0 \u05DE\u05EA\u05D7\u05D9\u05D9\u05D1 \u05E9\u05D4\u05DE\u05D5\u05E6\u05E8\u05D9\u05DD \u05E0\u05D9\u05EA\u05E0\u05D9\u05DD \u05DC\u05DE\u05DB\u05D9\u05E8\u05D4 \u05D5\u05DE\u05E9\u05DC\u05D5\u05D7 \u05D7\u05D5\u05E7\u05D9\u05D9\u05DD \u05DC\u05DE\u05D3\u05D9\u05E0\u05D5\u05EA \u05D4\u05E8\u05DC\u05D5\u05D5\u05E0\u05D8\u05D9\u05D5\u05EA \u05D5\u05DC\u05E6\u05D9\u05D9\u05EA \u05D0\u05EA \u05DB\u05DC \u05D4\u05D7\u05D5\u05E7\u05D9\u05DD \u05D5\u05D4\u05EA\u05E7\u05E0\u05D5\u05EA \u05D1\u05DE\u05D3\u05D9\u05E0\u05D5\u05EA \u05D4\u05DE\u05D5\u05E6\u05D0, \u05D4\u05DE\u05E2\u05D1\u05E8 \u05D5\u05D4\u05D9\u05E2\u05D3.' },
      { h: '29. \u05E2\u05D9\u05D1\u05D5\u05D3 \u05EA\u05E9\u05DC\u05D5\u05DE\u05D9\u05DD', p: '\u05EA\u05E9\u05DC\u05D5\u05DE\u05D9\u05DD \u05DE\u05E2\u05D5\u05D1\u05D3\u05D9\u05DD \u05E2\u05DC \u05D9\u05D3\u05D9 \u05E1\u05E4\u05E7\u05D9 \u05E9\u05D9\u05E8\u05D5\u05EA\u05D9 \u05EA\u05E9\u05DC\u05D5\u05DD \u05E6\u05D3 \u05E9\u05DC\u05D9\u05E9\u05D9 \u05D1\u05D4\u05E8\u05E9\u05D0\u05EA ShaPop. \u05D4\u05E9\u05D9\u05DE\u05D5\u05E9 \u05D1\u05E4\u05DC\u05D8\u05E4\u05D5\u05E8\u05DE\u05D4 \u05DE\u05D4\u05D5\u05D5\u05D4 \u05E7\u05D1\u05DC\u05EA \u05D4\u05EA\u05E0\u05D0\u05D9\u05DD \u05E9\u05DC \u05E1\u05E4\u05E7\u05D9\u05DD \u05D0\u05DC\u05D4. ShaPop \u05DE\u05D5\u05E8\u05E9\u05D9\u05EA \u05DC\u05E0\u05DB\u05D5\u05EA \u05D0\u05D5\u05D8\u05D5\u05DE\u05D8\u05D9\u05EA \u05D0\u05EA \u05D4\u05E2\u05DE\u05DC\u05D4, \u05D4\u05D3\u05DE\u05D9\u05DD \u05D5\u05DB\u05DC \u05E1\u05DB\u05D5\u05DD \u05D4\u05DE\u05D2\u05D9\u05E2 \u05D1\u05D2\u05D9\u05DF \u05E7\u05E0\u05E1\u05D5\u05EA, \u05D4\u05D7\u05D6\u05E8\u05D9\u05DD \u05D0\u05D5 \u05D4\u05EA\u05D0\u05DE\u05D5\u05EA \u05DC\u05E4\u05E0\u05D9 \u05D4\u05E2\u05D1\u05E8\u05EA \u05D4\u05D9\u05EA\u05E8\u05D4 \u05DC\u05DE\u05D5\u05DB\u05E8.' },
      { h: '30. \u05D4\u05D7\u05D6\u05E8\u05D9\u05DD, \u05E2\u05E8\u05E2\u05D5\u05E8\u05D9\u05DD \u05D5\u05D4\u05D7\u05D6\u05E8\u05D9 \u05D7\u05D9\u05D5\u05D1', p: '\u05D1\u05DE\u05E7\u05E8\u05D4 \u05E9\u05DC \u05D4\u05D7\u05D6\u05E8, \u05E2\u05E8\u05E2\u05D5\u05E8 \u05EA\u05E9\u05DC\u05D5\u05DD, \u05D4\u05D7\u05D6\u05E8 \u05D1\u05E0\u05E7\u05D0\u05D9 (chargeback), \u05D7\u05E9\u05D3 \u05DC\u05D4\u05D5\u05E0\u05D0\u05D4 \u05D0\u05D5 \u05D4\u05E4\u05E8\u05EA \u05DB\u05DC\u05DC\u05D9 \u05E8\u05E9\u05EA\u05D5\u05EA \u05D4\u05DB\u05E8\u05D8\u05D9\u05E1\u05D9\u05DD \u05D0\u05D5 \u05E1\u05E4\u05E7\u05D9 \u05D4\u05EA\u05E9\u05DC\u05D5\u05DD, ShaPop \u05E9\u05D5\u05DE\u05E8\u05EA \u05DC\u05E2\u05E6\u05DE\u05D4 \u05D0\u05EA \u05D4\u05D6\u05DB\u05D5\u05EA \u05DC\u05D7\u05D9\u05D9\u05D1 \u05D0\u05EA \u05D4\u05DE\u05D5\u05DB\u05E8. ShaPop \u05E8\u05E9\u05D0\u05D9\u05EA \u05DC\u05E7\u05D6\u05D6 \u05E1\u05DB\u05D5\u05DE\u05D9\u05DD \u05D0\u05DC\u05D4 \u05DE\u05D5\u05DC \u05EA\u05E9\u05DC\u05D5\u05DE\u05D9\u05DD \u05DE\u05DE\u05EA\u05D9\u05E0\u05D9\u05DD \u05D0\u05D5 \u05E2\u05EA\u05D9\u05D3\u05D9\u05D9\u05DD, \u05DC\u05E2\u05DB\u05D1 \u05DB\u05E1\u05E4\u05D9\u05DD \u05D0\u05D5 \u05DC\u05D3\u05E8\u05D5\u05E9 \u05D4\u05D7\u05D6\u05E8 \u05D9\u05E9\u05D9\u05E8 \u05DE\u05D4\u05DE\u05D5\u05DB\u05E8. \u05D4\u05DE\u05D5\u05DB\u05E8 \u05DE\u05D0\u05E9\u05E8 \u05E9\u05D4\u05D0\u05D7\u05E8\u05D9\u05D5\u05EA \u05D4\u05E4\u05D9\u05E0\u05E0\u05E1\u05D9\u05EA \u05D4\u05E1\u05D5\u05E4\u05D9\u05EA \u05DC\u05E2\u05E1\u05E7\u05D4 \u05D7\u05DC\u05D4 \u05E2\u05DC\u05D9\u05D5.' },
      { h: '31. \u05E8\u05D6\u05E8\u05D1\u05EA \u05D1\u05D9\u05D8\u05D7\u05D5\u05DF \u05D5\u05E2\u05D9\u05DB\u05D5\u05D1', p: '\u05DC\u05E6\u05D5\u05E8\u05DA \u05E0\u05D9\u05D4\u05D5\u05DC \u05D4\u05D7\u05E9\u05D9\u05E4\u05D4 \u05DC\u05E1\u05D9\u05DB\u05D5\u05DF, ShaPop \u05E8\u05E9\u05D0\u05D9\u05EA, \u05DC\u05E4\u05D9 \u05E9\u05D9\u05E7\u05D5\u05DC \u05D3\u05E2\u05EA\u05D4, \u05DC\u05E2\u05DB\u05D1 \u05D4\u05E2\u05D1\u05E8\u05D5\u05EA, \u05DC\u05D4\u05D2\u05D1\u05D9\u05DC \u05E4\u05E2\u05D9\u05DC\u05D5\u05EA \u05DE\u05D5\u05DB\u05E8 \u05D0\u05D5 \u05DC\u05D4\u05E7\u05D9\u05DD \u05E8\u05D6\u05E8\u05D1\u05D4 \u05E4\u05D9\u05E0\u05E0\u05E1\u05D9\u05EA \u05DC\u05DE\u05E9\u05DA \u05D4\u05D6\u05DE\u05DF \u05D4\u05E0\u05D3\u05E8\u05E9 \u05DC\u05DB\u05D9\u05E1\u05D5\u05D9 \u05EA\u05D1\u05D9\u05E2\u05D5\u05EA \u05E4\u05D5\u05D8\u05E0\u05E6\u05D9\u05D0\u05DC\u05D9\u05D5\u05EA.' },
      { h: '32. \u05DE\u05E9\u05DC\u05D5\u05D7 \u05D1\u05D9\u05E0\u05DC\u05D0\u05D5\u05DE\u05D9 \u05D5\u05DE\u05DB\u05E1', p: '\u05DC\u05DB\u05DC \u05E2\u05E1\u05E7\u05D4 \u05D7\u05D5\u05E6\u05D4 \u05D2\u05D1\u05D5\u05DC\u05D5\u05EA, \u05D4\u05DE\u05D5\u05DB\u05E8 \u05D0\u05D7\u05E8\u05D0\u05D9 \u05DC\u05E2\u05DE\u05D9\u05D3\u05D4 \u05D1\u05D7\u05D5\u05D1\u05D5\u05EA \u05D9\u05D9\u05E6\u05D5\u05D0 \u05D5\u05D4\u05D4\u05E6\u05D4\u05E8\u05D5\u05EA \u05D4\u05E0\u05D3\u05E8\u05E9\u05D5\u05EA. \u05D4\u05E7\u05D5\u05E0\u05D4 \u05D0\u05D7\u05E8\u05D0\u05D9 \u05DC\u05DE\u05DB\u05E1\u05D9 \u05DE\u05DB\u05E1, \u05DE\u05D9\u05E1\u05D9 \u05D9\u05D9\u05D1\u05D5\u05D0 \u05D5\u05D3\u05DE\u05D9 \u05D0\u05D3\u05DE\u05D9\u05E0\u05D9\u05E1\u05D8\u05E8\u05E6\u05D9\u05D4 \u05D1\u05DE\u05D3\u05D9\u05E0\u05EA \u05D4\u05D9\u05E2\u05D3. ShaPop \u05D0\u05D9\u05E0\u05D4 \u05E4\u05D5\u05E2\u05DC\u05EA \u05DB\u05D9\u05D9\u05D1\u05D0\u05E0\u05D9\u05EA, \u05D9\u05D9\u05E6\u05D5\u05D0\u05E0\u05D9\u05EA, \u05DE\u05D5\u05D1\u05D9\u05DC\u05D4 \u05D0\u05D5 \u05DE\u05E6\u05D4\u05D9\u05E8\u05EA \u05DE\u05DB\u05E1.' },
      { h: '33. \u05E2\u05DE\u05D9\u05D3\u05D4 \u05D1\u05DB\u05DC\u05DC\u05D9 \u05EA\u05E9\u05DC\u05D5\u05DD', p: '\u05D4\u05DE\u05E9\u05EA\u05DE\u05E9\u05D9\u05DD \u05DE\u05E1\u05DB\u05D9\u05DE\u05D9\u05DD \u05DC\u05E6\u05D9\u05D9\u05EA \u05D0\u05EA \u05DB\u05DC \u05D4\u05DB\u05DC\u05DC\u05D9\u05DD \u05D4\u05D7\u05DC\u05D9\u05DD \u05E9\u05DC \u05E8\u05E9\u05EA\u05D5\u05EA \u05D4\u05DB\u05E8\u05D8\u05D9\u05E1\u05D9\u05DD \u05D5\u05D4\u05E9\u05D5\u05EA\u05E4\u05D9\u05DD \u05D4\u05E4\u05D9\u05E0\u05E0\u05E1\u05D9\u05D9\u05DD \u05D4\u05DE\u05E9\u05DE\u05E9\u05D9\u05DD \u05D0\u05EA \u05D4\u05E4\u05DC\u05D8\u05E4\u05D5\u05E8\u05DE\u05D4.' },
      { h: '34. \u05E1\u05DE\u05DB\u05D5\u05EA \u05D4\u05D2\u05E0\u05EA \u05D4\u05E4\u05DC\u05D8\u05E4\u05D5\u05E8\u05DE\u05D4', p: 'ShaPop \u05E8\u05E9\u05D0\u05D9\u05EA \u05DC\u05D4\u05E9\u05E2\u05D5\u05EA \u05D1\u05D0\u05D5\u05E4\u05DF \u05DE\u05D9\u05D9\u05D3\u05D9 \u05D0\u05EA \u05D4\u05D2\u05D9\u05E9\u05D4 \u05DC\u05E9\u05D9\u05E8\u05D5\u05EA\u05D9\u05DD, \u05DC\u05D7\u05E1\u05D5\u05DD \u05E2\u05E1\u05E7\u05D0\u05D5\u05EA \u05D0\u05D5 \u05DC\u05E2\u05DB\u05D1 \u05DB\u05E1\u05E4\u05D9\u05DD \u05DB\u05D0\u05E9\u05E8 \u05DE\u05D6\u05D5\u05D4\u05D4 \u05E1\u05D9\u05DB\u05D5\u05DF \u05DE\u05E9\u05E4\u05D8\u05D9, \u05E8\u05D2\u05D5\u05DC\u05D8\u05D5\u05E8\u05D9, \u05E4\u05D9\u05E0\u05E0\u05E1\u05D9 \u05D0\u05D5 \u05D4\u05D5\u05E0\u05D0\u05D4, \u05D0\u05D5 \u05DC\u05D1\u05E7\u05E9\u05EA \u05E8\u05E9\u05D5\u05EA \u05DE\u05D5\u05E1\u05DE\u05DB\u05EA.' },
    ],
  },
  fr: {
    title: 'Conditions d\'utilisation',
    updated: 'Dernière mise à jour : 16 février 2026',
    sections: [
      { h: '1. Acceptation des conditions', p: 'En accédant ou en utilisant l\'application ShaPop (« l\'Application »), vous acceptez d\'être lié par les présentes Conditions d\'utilisation (« les Conditions »). Si vous n\'êtes pas d\'accord, veuillez ne pas utiliser l\'Application. ShaPop est exploitée par ShaPop Ltd., société enregistrée en France.' },
      { h: '2. Éligibilité', p: 'Vous devez avoir au moins 18 ans pour utiliser ShaPop. En créant un compte, vous déclarez être en âge légal et avoir la capacité de conclure un accord contraignant.' },
      { h: '3. Inscription au compte', p: 'Vous devez fournir des informations exactes et complètes lors de la création de votre compte. Vous êtes responsable de la confidentialité de vos identifiants et de toutes les activités effectuées sous votre compte. Informez-nous immédiatement de toute utilisation non autorisée.' },
      { h: '4. Règles de la marketplace', p: 'ShaPop est une marketplace de shopping en direct qui met en relation acheteurs et vendeurs. Les vendeurs sont des parties indépendantes, et non des employés ou agents de ShaPop. ShaPop ne possède, ne fabrique ni n\'inspecte les articles listés. Les vendeurs sont seuls responsables de l\'exactitude des annonces, de la qualité des articles et du respect des lois applicables.' },
      { h: '5. Diffusion en direct', p: 'Lors des diffusions en direct, vous vous engagez à : (a) ne pas diffuser de contenu interdit, offensant ou illégal ; (b) ne pas recourir à des pratiques trompeuses ; (c) respecter toutes les lois applicables en matière de publicité et de protection des consommateurs ; (d) respecter les autres utilisateurs. ShaPop se réserve le droit d\'interrompre sans préavis les diffusions qui enfreignent ces règles.' },
      { h: '6. Achats et paiements', p: 'Tous les achats sont des transactions entre l\'acheteur et le vendeur. Les prix sont fixés par les vendeurs et affichés dans la devise locale. ShaPop traite les paiements via des prestataires tiers sécurisés. Des frais de service peuvent s\'appliquer aux transactions. Les conditions et frais de paiement sont affichés avant la confirmation de l\'achat.' },
      { h: '7. Livraison et retours', p: 'Les vendeurs sont responsables de l\'expédition des articles dans les délais indiqués. Les acheteurs peuvent demander un retour dans les 14 jours suivant la réception, conformément à le Code de la consommation français. Les remboursements sont effectués sur le moyen de paiement d\'origine dans un délai de 14 jours ouvrés après approbation du retour.' },
      { h: '8. Articles interdits', p: 'Les articles suivants ne peuvent pas être mis en vente : armes, drogues, contrefaçons, biens volés, matières dangereuses, tabac, alcool (sans licence), animaux vivants, restes humains, et tout article interdit par la loi française.' },
      { h: '9. Frais et versements aux vendeurs', p: 'ShaPop prélève les frais suivants sur chaque vente effectuée, déduits du versement au vendeur (tous les montants incluent la TVA à 20%) : (a) Commission plateforme : 8% HT du prix de vente + TVA = 9,60% TTC ; (b) Frais de traitement du paiement : 2,9% HT + 0,30\u20AC HT + TVA = 3,48% + 0,36\u20AC TTC (Stripe). Exemple : pour une vente de 50\u20AC, la commission plateforme est de 4,80\u20AC TTC, les frais de traitement sont de 2,10\u20AC TTC, total des frais : 6,90\u20AC, le vendeur reçoit 43,10\u20AC. Les versements sont traités chaque semaine sur le compte bancaire enregistré du vendeur, sous réserve d\'un seuil minimum de 50\u20AC. Les frais sont susceptibles d\'évoluer avec un préavis de 30 jours.' },
      { h: '10. Propriété intellectuelle', p: 'L\'ensemble des marques, logos et contenus de ShaPop sont la propriété de ShaPop Ltd. Les utilisateurs conservent la propriété du contenu qu\'ils créent, mais accordent à ShaPop une licence mondiale, non exclusive et libre de redevances pour utiliser, afficher et distribuer ce contenu au sein de la plateforme.' },
      { h: '11. Conduite des utilisateurs', p: 'Vous vous engagez à ne pas : (a) enfreindre les lois ou réglementations ; (b) harceler, menacer ou escroquer d\'autres utilisateurs ; (c) publier du contenu faux ou trompeur ; (d) tenter d\'accéder de manière non autorisée à l\'Application ; (e) utiliser des bots ou des outils automatisés ; (f) manipuler les avis ou les notes.' },
      { h: '12. Limitation de responsabilité', p: 'Dans toute la mesure permise par la loi, ShaPop ne pourra être tenue responsable des dommages indirects, accessoires, spéciaux ou consécutifs. La responsabilité totale de ShaPop ne pourra excéder le montant que vous avez payé au cours des 12 mois précédant la réclamation.' },
      { h: '13. Résolution des litiges', p: 'Pour les litiges entre acheteurs et vendeurs, ShaPop propose un service de médiation. En cas d\'échec de la médiation, les litiges seront tranchés par les tribunaux compétents de Paris, France.' },
      { h: '14. Résiliation', p: 'ShaPop peut suspendre ou résilier votre compte à tout moment en cas de violation des présentes Conditions. Vous pouvez supprimer votre compte à tout moment via les paramètres de l\'Application. En cas de résiliation, les transactions en cours seront menées à terme.' },
      { h: '15. Modifications', p: 'ShaPop se réserve le droit de modifier les présentes Conditions à tout moment. Les modifications substantielles seront notifiées via l\'Application ou par e-mail au moins 30 jours avant leur entrée en vigueur. L\'utilisation continue après les modifications vaut acceptation.' },
      { h: '16. Droit applicable', p: 'Les présentes Conditions sont régies par les lois de la France. Toute procédure judiciaire sera portée exclusivement devant les tribunaux de Paris.' },
      { h: '17. Contact', p: 'Pour toute question relative aux présentes Conditions, contactez-nous à : shapopcontact@gmail.com' },
      { h: 'DISPOSITIONS SPÉCIFIQUES À L\'ACTIVITÉ DE MARKETPLACE', p: '' },
      { h: '18. Rôle de la plateforme', p: 'ShaPop agit en qualité d\'intermédiaire technique mettant en relation des acheteurs et des vendeurs via l\'Application. ShaPop n\'est pas le vendeur des biens proposés et n\'est jamais partie au contrat de vente conclu entre l\'acheteur et le vendeur. Le contrat de vente est formé directement entre l\'acheteur et le vendeur. Le vendeur est seul responsable de l\'offre, de la description, de la conformité, de la livraison et du service après-vente des produits.' },
      { h: '19. Responsabilités du vendeur', p: 'Le vendeur garantit qu\'il dispose de tous les droits, titres, autorisations et capacités nécessaires pour proposer et vendre les biens sur la plateforme. Il garantit que les produits respectent l\'ensemble des lois et réglementations applicables dans les pays d\'origine, de destination et de transit. Le vendeur est seul responsable : de l\'exactitude des descriptions, photographies et représentations des produits ; de l\'authenticité et de la provenance des articles ; de ses obligations fiscales et déclaratives ; des formalités douanières, licences d\'exportation ou d\'importation ; de l\'expédition, du transport, de l\'assurance et de la livraison ; du traitement des réclamations clients et du service après-vente.' },
      { h: '20. Traitement des paiements', p: 'Les paiements réalisés sur l\'Application sont traités par des prestataires de services de paiement tiers mandatés par ShaPop. L\'utilisation du service implique l\'acceptation des conditions propres à ces prestataires. ShaPop est autorisée à prélever automatiquement sur chaque transaction sa commission, les frais applicables, ainsi que tout montant dû au titre de pénalités, remboursements, litiges ou ajustements avant reversement du solde au vendeur.' },
      { h: '21. Remboursements, contestations et compensations', p: 'En cas de remboursement, de rétrofacturation bancaire (chargeback), de fraude suspectée, de réclamation d\'acheteur ou de violation des règles de paiement, ShaPop se réserve le droit de débiter le compte du vendeur concerné. ShaPop pourra compenser ces montants avec des paiements en attente ou futurs, ou exiger un règlement direct du vendeur si les fonds disponibles sont insuffisants. Le vendeur autorise irrévocablement ces déductions et reconnaît que la responsabilité financière finale liée à la transaction lui incombe.' },
      { h: '22. Réserve de sécurité et retenue des fonds', p: 'ShaPop peut, à sa seule discrétion, retarder, suspendre ou conditionner des versements, ou constituer une réserve financière lorsqu\'un niveau de risque, un volume inhabituel de litiges, une suspicion de fraude ou une exigence réglementaire est identifié. Cette réserve peut être maintenue pendant une durée raisonnablement nécessaire à la gestion du risque.' },
      { h: '23. Expédition internationale et douanes', p: 'Pour toute transaction impliquant un envoi transfrontalier, le vendeur est responsable du respect de l\'ensemble des obligations liées à l\'exportation. L\'acheteur est responsable des droits de douane, taxes d\'importation et frais administratifs applicables dans le pays de destination. ShaPop n\'agit pas en qualité d\'importateur, d\'exportateur, de transporteur ou de déclarant en douane.' },
      { h: '24. Conformité aux règles des réseaux de paiement', p: 'Les utilisateurs acceptent de respecter l\'ensemble des règles applicables imposées par les réseaux de cartes, établissements financiers et prestataires de services de paiement utilisés par la plateforme.' },
      { h: '25. Pouvoir de suspension ou de résiliation', p: 'ShaPop peut suspendre, restreindre ou résilier l\'accès à l\'Application ou aux services de paiement, immédiatement et sans préavis, en cas de risque juridique, réglementaire ou financier, de suspicion de fraude, de non-respect des présentes conditions ou à la demande d\'une autorité compétente.' },
      { h: '26. Limitation du rôle de ShaPop', p: 'ShaPop n\'exerce aucun contrôle sur la qualité, la sécurité, la légalité ou la conformité des biens vendus. La responsabilité de ShaPop ne saurait être engagée au titre des transactions conclues entre acheteurs et vendeurs, sauf obligation légale impérative contraire.' },
      { h: 'DISPOSITIONS COMPL\u00C9MENTAIRES \u2013 PAIEMENTS, RISQUES ET TRANSACTIONS INTERNATIONALES', p: '' },
      { h: '27. Rôle de ShaPop', p: 'ShaPop agit exclusivement en qualité d\'intermédiaire technique mettant en relation acheteurs et vendeurs. ShaPop n\'est jamais partie au contrat de vente conclu entre l\'acheteur et le vendeur. Chaque vendeur demeure seul responsable des produits proposés, de leur conformité, de leur légalité, de leur livraison et du service après-vente.' },
      { h: '28. Conformité des biens et capacité à vendre', p: 'Le vendeur garantit qu\'il dispose de tous les droits, autorisations et capacités nécessaires pour proposer les biens sur la plateforme. Il s\'engage à ce que les produits puissent être légalement vendus et expédiés vers les pays concernés par la transaction et à respecter l\'ensemble des lois et réglementations applicables dans le pays d\'origine, de transit et de destination.' },
      { h: '29. Traitement des paiements', p: 'Les paiements sont traités par des prestataires de services de paiement tiers mandatés par ShaPop. L\'utilisation de la plateforme implique l\'acceptation des conditions de ces prestataires. ShaPop est autorisée à prélever automatiquement sa commission, les frais applicables, ainsi que tout montant dû au titre de pénalités, remboursements ou ajustements avant reversement au vendeur.' },
      { h: '30. Remboursements, contestations et rétrofacturations', p: 'En cas de remboursement, de contestation de paiement, de rétrofacturation bancaire (chargeback), de fraude suspectée ou de violation des règles imposées par les réseaux de cartes ou les prestataires de paiement, ShaPop se réserve le droit de débiter le vendeur concerné. ShaPop pourra compenser ces montants avec des paiements en attente ou futurs, retenir des fonds ou exiger un remboursement direct du vendeur lorsque les sommes disponibles sont insuffisantes. Le vendeur reconnaît que la responsabilité financière finale liée à la transaction lui incombe.' },
      { h: '31. Réserve de sécurité et retenue', p: 'Afin de gérer l\'exposition au risque, ShaPop peut, à sa seule discrétion, retarder des versements, plafonner l\'activité d\'un vendeur ou constituer une réserve financière pendant la durée raisonnablement nécessaire à la couverture de réclamations potentielles.' },
      { h: '32. Expédition internationale et douanes', p: 'Pour toute transaction transfrontalière, le vendeur est responsable du respect des obligations d\'exportation et des déclarations nécessaires. L\'acheteur est responsable des droits de douane, taxes d\'importation et frais administratifs applicables dans le pays de destination. ShaPop n\'agit pas en qualité d\'importateur, d\'exportateur, de transporteur ou de déclarant en douane.' },
      { h: '33. Conformité aux règles de paiement', p: 'Les utilisateurs acceptent de respecter l\'ensemble des règles applicables imposées par les réseaux de cartes et les partenaires financiers utilisés par la plateforme.' },
      { h: '34. Pouvoir de protection de la plateforme', p: 'ShaPop peut suspendre immédiatement l\'accès aux services, bloquer des transactions ou retenir des fonds lorsqu\'un risque juridique, réglementaire, financier ou de fraude est identifié, ou sur demande d\'une autorité compétente.' },
    ],
  },
  es: {
    title: 'Terminos de Servicio',
    updated: 'Ultima actualizacion: 16 de febrero de 2026',
    sections: [
      { h: '1. Aceptacion de Terminos', p: 'Al acceder o usar la aplicacion ShaPop ("App"), aceptas estos Terminos de Servicio ("Terminos"). Si no estas de acuerdo, no uses la App. ShaPop es operada por ShaPop Ltd., registrada en Francia.' },
      { h: '2. Elegibilidad', p: 'Debes tener al menos 18 anos para usar ShaPop. Al crear una cuenta, declaras que tienes la edad legal y la capacidad para celebrar un acuerdo vinculante.' },
      { h: '3. Registro de Cuenta', p: 'Debes proporcionar informacion precisa y completa al crear tu cuenta. Eres responsable de mantener la confidencialidad de tus credenciales y de todas las actividades bajo tu cuenta.' },
      { h: '4. Reglas del Marketplace', p: 'ShaPop es un marketplace de compras en vivo que conecta compradores y vendedores. Los vendedores son partes independientes. ShaPop no posee, fabrica ni inspecciona los articulos listados.' },
      { h: '5. Transmisiones en Vivo', p: 'Al realizar transmisiones en vivo, aceptas: (a) no transmitir contenido prohibido u ofensivo; (b) no usar practicas enganosas; (c) cumplir con las leyes de proteccion al consumidor; (d) respetar a otros usuarios.' },
      { h: '6. Compras y Pagos', p: 'Las compras son transacciones entre comprador y vendedor. Los precios se muestran en la moneda local. ShaPop procesa pagos a traves de proveedores externos seguros. Una comision de servicio puede aplicarse.' },
      { h: '7. Envio y Devoluciones', p: 'Los vendedores son responsables del envio. Los compradores pueden solicitar una devolucion dentro de los 14 dias siguientes a la recepcion, conforme a la Codigo de Proteccion al Consumidor Frances (Code de la consommation).' },
      { h: '8. Articulos Prohibidos', p: 'No se pueden listar: armas, drogas, productos falsificados, propiedad robada, materiales peligrosos, tabaco, alcohol (sin licencia), animales vivos, y cualquier articulo prohibido por la ley francesa.' },
      { h: '9. Comisiones del Vendedor', p: 'ShaPop cobra las siguientes comisiones por cada venta completada, deducidas del pago al vendedor (todos los importes incluyen IVA al 20%): (a) Comision plataforma: 8% + IVA = 9,60%; (b) Procesamiento de pago: 2,9% + 0,30\u20AC + IVA = 3,48% + 0,36\u20AC (Stripe). Ejemplo: venta de 50\u20AC, comisiones totales 6,90\u20AC, el vendedor recibe 43,10\u20AC. Pagos semanales. Minimo: 50\u20AC. Comisiones sujetas a cambio con 30 dias de preaviso.' },
      { h: '10. Propiedad Intelectual', p: 'Toda la marca y contenido de ShaPop pertenecen a ShaPop Ltd. Los usuarios conservan la propiedad de su contenido pero otorgan a ShaPop una licencia mundial y no exclusiva para usarlo en la plataforma.' },
      { h: '11. Conducta del Usuario', p: 'Aceptas no: (a) violar leyes; (b) acosar o amenazar; (c) publicar contenido falso; (d) intentar acceso no autorizado; (e) usar bots; (f) manipular resenas.' },
      { h: '12. Limitacion de Responsabilidad', p: 'En la medida maxima permitida por la ley, ShaPop no sera responsable por danos indirectos. La responsabilidad total de ShaPop no excedera el monto pagado en los 12 meses anteriores.' },
      { h: '13. Resolucion de Disputas', p: 'ShaPop ofrece un servicio de mediacion. Si la mediacion falla, las disputas se resolveran en los tribunales competentes de Paris, Francia.' },
      { h: '14. Terminacion', p: 'ShaPop puede suspender o terminar tu cuenta por violacion de estos Terminos. Puedes eliminar tu cuenta en cualquier momento.' },
      { h: '15. Modificaciones', p: 'ShaPop se reserva el derecho de modificar estos Terminos. Los cambios materiales se notificaran con al menos 30 dias de anticipacion.' },
      { h: '16. Ley Aplicable', p: 'Estos Terminos se rigen por las leyes de Francia. Los procedimientos legales se llevaran exclusivamente en los tribunales de Paris.' },
      { h: '17. Contacto', p: 'Para preguntas sobre estos Terminos: shapopcontact@gmail.com' },
      { h: 'DISPOSICIONES ESPECÍFICAS DE LA ACTIVIDAD DE MARKETPLACE', p: '' },
      { h: '18. Rol de la plataforma', p: 'ShaPop actua como intermediario tecnico que conecta compradores y vendedores a traves de la Aplicacion. ShaPop no es el vendedor de los bienes ofrecidos y nunca es parte del contrato de venta celebrado entre el comprador y el vendedor. El contrato de venta se celebra directamente entre el comprador y el vendedor. El vendedor es el unico responsable de la oferta, descripcion, conformidad, entrega y servicio postventa de los productos.' },
      { h: '19. Responsabilidades del vendedor', p: 'El vendedor garantiza que dispone de todos los derechos, titulos, autorizaciones y capacidades necesarios para ofrecer y vender bienes en la plataforma. Garantiza que los productos cumplen con todas las leyes y regulaciones aplicables en los paises de origen, destino y transito. El vendedor es el unico responsable de: la exactitud de las descripciones, fotografias y representaciones de los productos; la autenticidad y procedencia de los articulos; sus obligaciones fiscales y declarativas; los tramites aduaneros, licencias de exportacion o importacion; el envio, transporte, seguro y entrega; el tratamiento de reclamaciones de clientes y servicio postventa.' },
      { h: '20. Procesamiento de pagos', p: 'Los pagos realizados en la Aplicacion son procesados por proveedores de servicios de pago terceros autorizados por ShaPop. El uso del servicio implica la aceptacion de los terminos de dichos proveedores. ShaPop esta autorizada a deducir automaticamente de cada transaccion su comision, los cargos aplicables y cualquier monto adeudado por penalizaciones, reembolsos, disputas o ajustes antes de transferir el saldo al vendedor.' },
      { h: '21. Reembolsos, disputas y compensaciones', p: 'En caso de reembolso, contracargo bancario (chargeback), sospecha de fraude, reclamacion del comprador o violacion de las reglas de pago, ShaPop se reserva el derecho de debitar la cuenta del vendedor correspondiente. ShaPop podra compensar estos montos con pagos pendientes o futuros, o exigir un pago directo del vendedor si los fondos disponibles son insuficientes. El vendedor autoriza irrevocablemente estas deducciones y reconoce que la responsabilidad financiera final de la transaccion recae sobre el.' },
      { h: '22. Reserva de seguridad y retencion de fondos', p: 'ShaPop puede, a su sola discrecion, retrasar, suspender o condicionar los pagos, o constituir una reserva financiera cuando se identifique un nivel de riesgo, un volumen inusual de disputas, sospecha de fraude o un requisito regulatorio. Esta reserva puede mantenerse durante el periodo razonablemente necesario para la gestion del riesgo.' },
      { h: '23. Envio internacional y aduanas', p: 'Para cualquier transaccion que implique un envio transfronterizo, el vendedor es responsable del cumplimiento de todas las obligaciones de exportacion. El comprador es responsable de los derechos de aduana, impuestos de importacion y gastos administrativos aplicables en el pais de destino. ShaPop no actua como importador, exportador, transportista o declarante aduanero.' },
      { h: '24. Cumplimiento de las reglas de las redes de pago', p: 'Los usuarios aceptan cumplir con todas las reglas aplicables impuestas por las redes de tarjetas, instituciones financieras y proveedores de servicios de pago utilizados por la plataforma.' },
      { h: '25. Poder de suspension o terminacion', p: 'ShaPop puede suspender, restringir o terminar el acceso a la Aplicacion o a los servicios de pago, inmediatamente y sin previo aviso, en caso de riesgo legal, regulatorio o financiero, sospecha de fraude, incumplimiento de estos terminos o a solicitud de una autoridad competente.' },
      { h: '26. Limitacion del rol de ShaPop', p: 'ShaPop no ejerce ningun control sobre la calidad, seguridad, legalidad o conformidad de los bienes vendidos. La responsabilidad de ShaPop no podra ser invocada en relacion con las transacciones celebradas entre compradores y vendedores, salvo obligacion legal imperativa en contrario.' },
      { h: 'DISPOSICIONES COMPLEMENTARIAS \u2013 PAGOS, RIESGOS Y TRANSACCIONES INTERNACIONALES', p: '' },
      { h: '27. Rol de ShaPop', p: 'ShaPop actua exclusivamente como intermediario tecnico que conecta compradores y vendedores. ShaPop nunca es parte del contrato de venta celebrado entre el comprador y el vendedor. Cada vendedor es el unico responsable de los productos ofrecidos, de su conformidad, de su legalidad, de su entrega y del servicio postventa.' },
      { h: '28. Conformidad de los bienes y capacidad para vender', p: 'El vendedor garantiza que dispone de todos los derechos, autorizaciones y capacidades necesarios para ofrecer los bienes en la plataforma. Se compromete a que los productos puedan ser legalmente vendidos y enviados a los paises involucrados en la transaccion y a cumplir con todas las leyes y regulaciones aplicables en el pais de origen, transito y destino.' },
      { h: '29. Procesamiento de pagos', p: 'Los pagos son procesados por proveedores de servicios de pago terceros autorizados por ShaPop. El uso de la plataforma implica la aceptacion de los terminos de dichos proveedores. ShaPop esta autorizada a deducir automaticamente su comision, los cargos aplicables y cualquier monto adeudado por penalizaciones, reembolsos o ajustes antes de transferir el saldo al vendedor.' },
      { h: '30. Reembolsos, disputas y contracargos', p: 'En caso de reembolso, disputa de pago, contracargo bancario (chargeback), sospecha de fraude o violacion de las reglas impuestas por las redes de tarjetas o proveedores de pago, ShaPop se reserva el derecho de debitar al vendedor correspondiente. ShaPop podra compensar estos montos con pagos pendientes o futuros, retener fondos o exigir un reembolso directo del vendedor cuando los fondos disponibles sean insuficientes. El vendedor reconoce que la responsabilidad financiera final de la transaccion recae sobre el.' },
      { h: '31. Reserva de seguridad y retencion', p: 'Para gestionar la exposicion al riesgo, ShaPop puede, a su sola discrecion, retrasar los pagos, limitar la actividad de un vendedor o constituir una reserva financiera durante el periodo razonablemente necesario para cubrir reclamaciones potenciales.' },
      { h: '32. Envio internacional y aduanas', p: 'Para cualquier transaccion transfronteriza, el vendedor es responsable del cumplimiento de las obligaciones de exportacion y las declaraciones necesarias. El comprador es responsable de los derechos de aduana, impuestos de importacion y gastos administrativos aplicables en el pais de destino. ShaPop no actua como importador, exportador, transportista o declarante aduanero.' },
      { h: '33. Cumplimiento de las reglas de pago', p: 'Los usuarios aceptan cumplir con todas las reglas aplicables impuestas por las redes de tarjetas y los socios financieros utilizados por la plataforma.' },
      { h: '34. Poder de proteccion de la plataforma', p: 'ShaPop puede suspender inmediatamente el acceso a los servicios, bloquear transacciones o retener fondos cuando se identifique un riesgo legal, regulatorio, financiero o de fraude, o a solicitud de una autoridad competente.' },
    ],
  },
}

export default function TermsPage() {
  const navigate = useNavigate()
  const lang = getLang()
  const c = content[lang] || content.fr
  usePageTitle(c.title)

  return (
    <div style={{ minHeight: '100vh', backgroundColor: '#000', paddingBottom: '80px' }}>
      <div style={{ position: 'sticky', top: 0, zIndex: 10, backgroundColor: '#000', borderBottom: '1px solid #1A1A1A', padding: '12px 16px', paddingTop: 'calc(env(safe-area-inset-top, 0px) + 12px)', display: 'flex', alignItems: 'center', gap: '12px' }}>
        <button onClick={() => navigate(-1)} aria-label="Go back" style={{ background: 'none', border: 'none', cursor: 'pointer', padding: '4px' }}>
          <svg width="24" height="24" viewBox="0 0 24 24" fill="none" stroke="#fff" strokeWidth="2" style={{...rtlFlip()}}><path d="M19 12H5M12 19l-7-7 7-7" strokeLinecap="round" strokeLinejoin="round"/></svg>
        </button>
        <h1 style={{ fontSize: '18px', fontWeight: 700, color: '#fff' }}>{c.title}</h1>
      </div>
      <div style={{ padding: '20px 20px' }}>
        <p style={{ fontSize: '12px', color: '#666', marginBottom: '24px' }}>{c.updated}</p>
        {c.sections.map((s) => (
          <div key={s.h} style={{ marginBottom: s.p ? '20px' : '28px', marginTop: !s.p ? '32px' : undefined }}>
            <h2 style={{
              fontSize: s.p ? '15px' : '16px',
              fontWeight: 700,
              color: s.p ? '#fff' : '#F0908A',
              marginBottom: s.p ? '6px' : '0',
              textTransform: s.p ? undefined : 'uppercase' as const,
              letterSpacing: s.p ? undefined : '0.5px',
            }}>{s.h}</h2>
            {s.p && <p style={{ fontSize: '14px', color: '#aaa', lineHeight: 1.6 }}>{s.p}</p>}
          </div>
        ))}
      </div>
    </div>
  )
}
